/* The Grounded Readings Library, group prot2 (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["prot2"] = [{"id":"prot-jw-isaiah-65","title":"They Shall Build Houses (Isaiah 65:21 to 23)","by":"American Standard Version","year":1901,"trad":["jw","christian"],"type":"scripture","occasion":["hope","home"],"text":"And they shall build houses, and inhabit them; and they shall plant vineyards, and eat the fruit of them.\nThey shall not build, and another inhabit; they shall not plant, and another eat: for as the days of a tree shall be the days of my people, and my chosen shall long enjoy the work of their hands.\nThey shall not labor in vain, nor bring forth for calamity; for they are the seed of the blessed of Jehovah, and their offspring with them.","note":"A picture of the peaceful earth to come.","voice":"brian","source":{"name":"American Standard Version (1901), Isaiah 65:21-23","url":"https://www.biblegateway.com/passage/?search=Isaiah+65%3A21-23&version=ASV"},"rights":"pd","pd":"American Standard Version, published 1901.","denom":[]},{"id":"prot-cs-lords-prayer","title":"The Spiritual Sense of the Lord's Prayer","by":"Mary Baker Eddy","year":1875,"trad":["cs","christian"],"type":"prayer","occasion":["daily","healing"],"text":"Our Father which art in heaven,\nOur Father-Mother God, all-harmonious,\n\nHallowed be Thy name.\nAdorable One.\n\nThy kingdom come.\nThy kingdom is come; Thou art ever-present.\n\nThy will be done in earth, as it is in heaven.\nEnable us to know, as in heaven, so on earth, God is omnipotent, supreme.\n\nGive us this day our daily bread;\nGive us grace for to-day; feed the famished affections;\n\nAnd forgive us our debts, as we forgive our debtors.\nAnd Love is reflected in love;\n\nAnd lead us not into temptation, but deliver us from evil;\nAnd God leadeth us not into temptation, but delivereth us from sin, disease, and death.\n\nFor Thine is the kingdom, and the power, and the glory, forever.\nFor God is infinite, all-power, all Life, Truth, Love, over all, and All.","note":"Prayed aloud in every Christian Science Sunday service.","voice":"brian","source":{"name":"Mary Baker Eddy, Science and Health with Key to the Scriptures (1910)","url":"https://www.gutenberg.org/ebooks/3458"},"rights":"pd","pd":"Final edition 1910; Eddy died 1910.","denom":[]},{"id":"prot-cs-scientific-statement","title":"The Scientific Statement of Being","by":"Mary Baker Eddy","year":1875,"trad":["cs"],"type":"reflection","occasion":["funeral","healing","daily"],"text":"There is no life, truth, intelligence, nor substance in matter. All is infinite Mind and its infinite manifestation, for God is All-in-all. Spirit is immortal Truth; matter is mortal error. Spirit is the real and eternal; matter is the unreal and temporal. Spirit is God, and man is His image and likeness. Therefore man is not material; he is spiritual.","note":"Read at the close of the Christian Science Sunday lesson.","voice":"jenny","source":{"name":"Mary Baker Eddy, Science and Health with Key to the Scriptures (1910)","url":"https://www.gutenberg.org/ebooks/3458"},"rights":"pd","pd":"Final edition 1910; Eddy died 1910.","denom":[]},{"id":"prot-cs-divine-love","title":"Divine Love Always Has Met","by":"Mary Baker Eddy","year":1875,"trad":["cs"],"type":"reflection","occasion":["comfort","healing"],"text":"Divine Love always has met and always will meet every human need. It is not well to imagine that Jesus demonstrated the divine power to heal only for a select number or for a limited period of time, since to all mankind and in every hour, divine Love supplies all good.","note":"One of the most quoted lines of Science and Health, from page 494.","voice":"brian","source":{"name":"Mary Baker Eddy, Science and Health with Key to the Scriptures (1910)","url":"https://www.gutenberg.org/ebooks/3458"},"rights":"pd","pd":"Final edition 1910; Eddy died 1910.","denom":[]},{"id":"prot-cs-life-is-eternal","title":"Life Is Eternal","by":"Mary Baker Eddy","year":1875,"trad":["cs"],"type":"reflection","occasion":["funeral","hope"],"text":"Life is eternal. We should find this out, and begin the demonstration thereof. Life and goodness are immortal. Let us then shape our views of existence into loveliness, freshness, and continuity, rather than into age and blight.","note":"From page 246, a word on the continuity of life.","voice":"jenny","source":{"name":"Mary Baker Eddy, Science and Health with Key to the Scriptures (1910)","url":"https://www.gutenberg.org/ebooks/3458"},"rights":"pd","pd":"Final edition 1910; Eddy died 1910.","denom":[]},{"id":"prot-cs-desire-is-prayer","title":"Desire Is Prayer","by":"Mary Baker Eddy","year":1875,"trad":["cs"],"type":"reflection","occasion":["daily","peace"],"text":"Thoughts unspoken are not unknown to the divine Mind. Desire is prayer; and no loss can occur from trusting God with our desires, that they may be moulded and exalted before they take form in words and in deeds.","note":"From the opening chapter of Science and Health, on prayer.","voice":"brian","source":{"name":"Mary Baker Eddy, Science and Health with Key to the Scriptures (1910)","url":"https://www.gutenberg.org/ebooks/3458"},"rights":"pd","pd":"Final edition 1910; Eddy died 1910.","denom":[]},{"id":"prot-cs-daily-prayer","title":"The Daily Prayer","by":"Mary Baker Eddy","year":1895,"trad":["cs"],"type":"prayer","occasion":["daily","morning"],"text":"\"Thy kingdom come;\" let the reign of divine Truth, Life, and Love be established in me, and rule out of me all sin; and may Thy Word enrich the affections of all mankind, and govern them!","note":"From the Manual of The Mother Church, prayed daily by members.","voice":"jenny","source":{"name":"Mary Baker Eddy, Manual of The Mother Church (89th edition, 1910)","url":"https://www.gutenberg.org/ebooks/search/?query=manual+of+the+mother+church"},"rights":"pd","pd":"Manual first published 1895; Eddy died 1910.","denom":[]},{"id":"prot-adv-1-thessalonians-4","title":"We Shall Ever Be with the Lord (1 Thessalonians 4:13 to 18)","by":"King James Version","year":1611,"trad":["adventist","christian"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope.\nFor if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him.\nFor this we say unto you by the word of the Lord, that we which are alive and remain unto the coming of the Lord shall not prevent them which are asleep.\nFor the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:\nThen we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.\nWherefore comfort one another with these words.","note":"The blessed hope of the Second Coming, read at nearly every Adventist funeral.","voice":"brian","source":{"name":"King James Version (1611), 1 Thessalonians 4:13-18","url":"https://www.biblegateway.com/passage/?search=1+Thessalonians+4%3A13-18&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-adv-isaiah-58","title":"Call the Sabbath a Delight (Isaiah 58:13 to 14)","by":"King James Version","year":1611,"trad":["adventist","christian"],"type":"scripture","occasion":["daily","blessing","home"],"text":"If thou turn away thy foot from the sabbath, from doing thy pleasure on my holy day; and call the sabbath a delight, the holy of the LORD, honourable; and shalt honour him, not doing thine own ways, nor finding thine own pleasure, nor speaking thine own words:\nThen shalt thou delight thyself in the LORD; and I will cause thee to ride upon the high places of the earth, and feed thee with the heritage of Jacob thy father: for the mouth of the LORD hath spoken it.","note":"Read at sundown Friday to welcome the Sabbath.","voice":"jenny","source":{"name":"King James Version (1611), Isaiah 58:13-14","url":"https://www.biblegateway.com/passage/?search=Isaiah+58%3A13-14&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-adv-john-11","title":"I Am the Resurrection (John 11:25 to 26)","by":"King James Version","year":1611,"trad":["adventist","christian"],"type":"scripture","occasion":["funeral","hope"],"text":"Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:\nAnd whosoever liveth and believeth in me shall never die. Believest thou this?","note":"Jesus at the grave of Lazarus, read at graveside services.","voice":"brian","source":{"name":"King James Version (1611), John 11:25-26","url":"https://www.biblegateway.com/passage/?search=John+11%3A25-26&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-adv-great-controversy","title":"God Is Love","by":"Ellen G. White","year":1888,"trad":["adventist","christian"],"type":"reflection","occasion":["funeral","hope","peace"],"text":"The great controversy is ended. Sin and sinners are no more. The entire universe is clean. One pulse of harmony and gladness beats through the vast creation. From Him who created all, flow life and light and gladness, throughout the realms of illimitable space. From the minutest atom to the greatest world, all things, animate and inanimate, in their unshadowed beauty and perfect joy, declare that God is love.","note":"The closing paragraph of The Great Controversy, read at Adventist funerals.","voice":"jenny","source":{"name":"Ellen G. White, The Great Controversy (1888), Ellen G. White Estate","url":"https://egwwritings.org/"},"rights":"pd","pd":"Published 1888; White died 1915.","denom":[]},{"id":"prot-adv-steps-to-christ","title":"Keep Your Wants Before God","by":"Ellen G. White","year":1892,"trad":["adventist","christian"],"type":"reflection","occasion":["comfort","daily"],"text":"Keep your wants, your joys, your sorrows, your cares, and your fears before God. You cannot burden Him; you cannot weary Him. He who numbers the hairs of your head is not indifferent to the wants of His children.","note":"From Steps to Christ, chapter on the privilege of prayer.","voice":"brian","source":{"name":"Ellen G. White, Steps to Christ (1892), Ellen G. White Estate","url":"https://egwwritings.org/"},"rights":"pd","pd":"Published 1892; White died 1915.","denom":[]},{"id":"prot-disciples-in-thee-o-lord","title":"In Thee, O Lord, I Put My Trust","by":"William Thomas Moore","year":1865,"trad":["disciples","christian"],"type":"hymn","occasion":["comfort","daily"],"text":"In thee, O Lord, I put my trust,\nThou art my portion and my song;\nThy ways, with me, are always just,\nBut mine, with thee, are often wrong.\n\nI can not do the things I would,\nFor sin is in my flesh concealed;\nSo evil takes the place of good,\nAnd all my weakness stands revealed.\n\nBut thou, O Lord, canst make me clean,\nAnd give me strength to do the right;\nWhile on thy promises I lean,\nAll darkness changes into light.\n\nO give me grace the wrong to shun,\nThe right to follow all my days,\nAnd when life's victory is won,\nThen will I give thee all the praise.","note":"A hymn by a Disciples of Christ editor, from the hymnbook Alexander Campbell began.","voice":"jenny","source":{"name":"The Christian Hymn Book, compiled by A. Campbell and others (1865; 1870 printing)","url":"https://www.gutenberg.org/ebooks/46041"},"rights":"pd","pd":"Published 1865; Moore died 1926.","denom":[]},{"id":"prot-disciples-kind-father","title":"Kind Father, Look with Pity Now","by":"William Thomas Moore","year":1865,"trad":["disciples","christian"],"type":"hymn","occasion":["forgiveness","healing"],"text":"Kind Father, look with pity now\nOn one by sin defiled;\nWhile at the mercy-seat I bow,\nO bless thy erring child.\n\nMy struggles, Lord, to do thy will,\nHow poor and weak they are!\nBut thou art gracious to me still,\nThen hear my humble prayer.\n\nLet love upon my broken heart\nPour out its healing balm;\nBid all my trembling fears depart,\nMy troubled spirit calm.\n\nAnd now my hope new courage takes,\nMy faith grows strong and sure;\nThe cloud from off my vision breaks,\nAgain my heart is pure.\n\nMy soul mounts up on wings of light\nAnd soars to climes above,\nThe regions where all things are bright,\nThe home of Peace and Love.\n\nThere, soon I'll sing of love divine,\nWith all the ransomed throng,\nThere, Jesus shall be ever mine,\nHis love my endless song.","note":"A Disciples hymn of mercy and new courage.","voice":"brian","source":{"name":"The Christian Hymn Book, compiled by A. Campbell and others (1865; 1870 printing)","url":"https://www.gutenberg.org/ebooks/46041"},"rights":"pd","pd":"Published 1865; Moore died 1926.","denom":[]},{"id":"prot-disciples-lords-supper","title":"The Lord's Supper (1 Corinthians 11:23 to 26)","by":"King James Version","year":1611,"trad":["disciples","christian"],"type":"scripture","occasion":["daily","gratitude"],"text":"For I have received of the Lord that which also I delivered unto you, That the Lord Jesus the same night in which he was betrayed took bread:\nAnd when he had given thanks, he brake it, and said, Take, eat: this is my body, which is broken for you: this do in remembrance of me.\nAfter the same manner also he took the cup, when he had supped, saying, This cup is the new testament in my blood: this do ye, as oft as ye drink it, in remembrance of me.\nFor as often as ye eat this bread, and drink this cup, ye do shew the Lord’s death till he come.","note":"Read at the Lord's Table, which Disciples of Christ gather around every Sunday.","voice":"jenny","source":{"name":"King James Version (1611), 1 Corinthians 11:23-26","url":"https://www.biblegateway.com/passage/?search=1+Corinthians+11%3A23-26&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-disciples-one-church","title":"Essentially, Intentionally, and Constitutionally One","by":"Thomas Campbell","year":1809,"trad":["disciples","christian"],"type":"reflection","occasion":["peace","blessing"],"text":"The church of Christ upon earth is essentially, intentionally, and constitutionally one.","note":"The first proposition of the Declaration and Address, the founding statement of the Disciples' unity movement.","voice":"brian","source":{"name":"Thomas Campbell, Declaration and Address (1809)","url":"https://www.gutenberg.org/ebooks/search/?query=declaration+and+address+campbell"},"rights":"pd","pd":"Published 1809.","denom":[]},{"id":"prot-disciples-in-essentials","title":"In Essentials, Unity","by":"Rupertus Meldenius","year":1626,"trad":["disciples","moravian","christian"],"type":"blessing","occasion":["peace","blessing","home"],"text":"In essentials, unity; in non-essentials, liberty; in all things, charity.","note":"A seventeenth century peacemaker's motto, adopted by the Disciples of Christ and the Moravian Church.","voice":"jenny","source":{"name":"Rupertus Meldenius, Paraenesis votiva pro pace ecclesiae (1626)","url":"https://www.moravian.org/the-moravian-church/the-moravian-church/"},"rights":"pd","pd":"Written 1626.","denom":[]},{"id":"prot-anabaptist-doxology","title":"Praise God from Whom All Blessings Flow","by":"Thomas Ken","year":1674,"trad":["anabaptist","christian"],"denom":["mennonite"],"type":"hymn","occasion":["gratitude","celebration","daily"],"text":"Praise God, from whom all blessings flow;\nPraise Him, all creatures here below;\nPraise Him above, ye heavenly host:\nPraise Father, Son, and Holy Ghost. Amen.","note":"Sung in many churches; among Mennonites it is sung in four part harmony as the beloved 606.","voice":"brian","source":{"name":"Little Folded Hands: Prayers for Children (Concordia, about 1918)","url":"https://www.gutenberg.org/ebooks/11149"},"rights":"pd","pd":"Ken died 1711."},{"id":"prot-anabaptist-john-13","title":"Ye Also Ought to Wash One Another's Feet (John 13:12 to 17)","by":"King James Version","year":1611,"trad":["anabaptist","christian"],"denom":["brethren","mennonite","amish"],"type":"scripture","occasion":["daily","blessing"],"text":"So after he had washed their feet, and had taken his garments, and was set down again, he said unto them, Know ye what I have done to you?\nYe call me Master and Lord: and ye say well; for so I am.\nIf I then, your Lord and Master, have washed your feet; ye also ought to wash one another’s feet.\nFor I have given you an example, that ye should do as I have done to you.\nVerily, verily, I say unto you, The servant is not greater than his lord; neither he that is sent greater than he that sent him.\nIf ye know these things, happy are ye if ye do them.","note":"Read at the love feast and feetwashing kept by Brethren, Mennonite, and Amish churches.","voice":"jenny","source":{"name":"King James Version (1611), John 13:12-17","url":"https://www.biblegateway.com/passage/?search=John+13%3A12-17&version=KJV"},"rights":"pd","pd":"King James Version, 1611."},{"id":"prot-anabaptist-beatitudes","title":"The Beatitudes (Matthew 5:3 to 10)","by":"King James Version","year":1611,"trad":["anabaptist","christian"],"denom":["mennonite","amish","brethren","hutterite"],"type":"scripture","occasion":["peace","comfort","funeral"],"text":"Blessed are the poor in spirit: for theirs is the kingdom of heaven.\nBlessed are they that mourn: for they shall be comforted.\nBlessed are the meek: for they shall inherit the earth.\nBlessed are they which do hunger and thirst after righteousness: for they shall be filled.\nBlessed are the merciful: for they shall obtain mercy.\nBlessed are the pure in heart: for they shall see God.\nBlessed are the peacemakers: for they shall be called the children of God.\nBlessed are they which are persecuted for righteousness’ sake: for theirs is the kingdom of heaven.","note":"The heart of the Sermon on the Mount, which shapes Anabaptist life and peacemaking.","voice":"brian","source":{"name":"King James Version (1611), Matthew 5:3-10","url":"https://www.biblegateway.com/passage/?search=Matthew+5%3A3-10&version=KJV"},"rights":"pd","pd":"King James Version, 1611."},{"id":"prot-menno-true-faith","title":"True Evangelical Faith","by":"Menno Simons","year":1539,"trad":["anabaptist","christian"],"denom":["mennonite"],"type":"reflection","occasion":["daily","blessing"],"text":"True evangelical faith cannot lie dormant. It clothes the naked, it feeds the hungry, it comforts the sorrowful, it shelters the destitute, it serves those that harm it, it binds up that which is wounded, it has become all things to all people.","note":"Menno Simons' most quoted words, dear to Mennonites and read at the funeral of one who served.","voice":"jenny","source":{"name":"Menno Simons, Why I Do Not Cease Teaching and Writing (1539), in The Complete Works (1871)","url":"https://www.gutenberg.org/ebooks/search/?query=menno+simons"},"rights":"pd","pd":"Written 1539."},{"id":"prot-heal-me-jesus","title":"Heal Me, Jesus","by":"Traditional spiritual","year":1909,"trad":["blackchurch","pentecostal","christian"],"type":"song","occasion":["healing","comfort"],"text":"O Lord, I'm sick an' I want to be healed,\nO Lord, I'm sick an' I want to be healed,\nO Lord, I'm sick an' I want to be healed,\nO Lord, I'm sick an' I want to be healed.\n\nHeal me Jesus, heal me Jesus,\nAlong the heavenly way,\nHeal me Jesus, heal me Jesus,\nAlong the heavenly way.","note":"A spiritual of plain, trusting prayer for healing, as collected in Georgia and Mississippi before 1909.","voice":"brian","source":{"name":"Howard W. Odum, Religious Folk-Songs of the Southern Negroes (1909)","url":"https://www.gutenberg.org/ebooks/39078"},"rights":"pd","pd":"Traditional; printed 1909.","denom":[]},{"id":"prot-steal-away-odum","title":"Steal Away to Jesus","by":"Traditional spiritual","year":1909,"trad":["blackchurch","christian"],"type":"song","occasion":["dying","peace","funeral"],"text":"O steal away, steal away,\nO steal away to my Jesus,\nSteal away, steal away,\nFor I ain't got long to stay here.\n\nMy Lord is a callin',\nPo' sinner he can't answer,\nWell, the trumpet sound in my soul,\nAn' I ain't got long to stay here.","note":"One of the oldest spirituals, sung at the bedside and at homegoing services.","voice":"jenny","source":{"name":"Howard W. Odum, Religious Folk-Songs of the Southern Negroes (1909)","url":"https://www.gutenberg.org/ebooks/39078"},"rights":"pd","pd":"Traditional; printed 1909.","denom":[]},{"id":"prot-balm-in-gilead","title":"There Is a Balm in Gilead","by":"Traditional spiritual","year":1854,"trad":["blackchurch","christian"],"type":"song","occasion":["healing","comfort","grief"],"text":"There is a balm in Gilead\nTo make the wounded whole;\nThere is a balm in Gilead\nTo heal the sin-sick soul.\n\nSometimes I feel discouraged,\nAnd think my work's in vain,\nBut then the Holy Spirit\nRevives my soul again.","note":"A spiritual answering Jeremiah's question with yes, sung for healing and at funerals.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=There+is+a+balm+in+Gilead"},"rights":"pd","pd":"Traditional, nineteenth century.","denom":[]},{"id":"prot-were-you-there","title":"Were You There","by":"Traditional spiritual","year":1899,"trad":["blackchurch","christian"],"type":"song","occasion":["season","grief"],"text":"Were you there when they crucified my Lord?\nWere you there when they crucified my Lord?\nOh! Sometimes it causes me to tremble, tremble, tremble.\nWere you there when they crucified my Lord?\n\nWere you there when they laid Him in the tomb?\nWere you there when they laid Him in the tomb?\nOh! Sometimes it causes me to tremble, tremble, tremble.\nWere you there when they laid Him in the tomb?","note":"A spiritual sung on Good Friday and at services of remembrance.","voice":"jenny","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Were+you+there+when+they+crucified+my+Lord"},"rights":"pd","pd":"Traditional, printed by 1899.","denom":[]},{"id":"prot-i-want-jesus-to-walk","title":"I Want Jesus to Walk with Me","by":"Traditional spiritual","year":1900,"trad":["blackchurch","christian"],"type":"song","occasion":["comfort","dying","grief"],"text":"I want Jesus to walk with me;\nI want Jesus to walk with me;\nAll along my pilgrim journey,\nLord, I want Jesus to walk with me.\n\nIn my trials, Lord, walk with me;\nIn my trials, Lord, walk with me;\nWhen my heart is almost breaking,\nLord, I want Jesus to walk with me.\n\nWhen I'm in trouble, Lord, walk with me;\nWhen I'm in trouble, Lord, walk with me;\nWhen my head is bowed in sorrow,\nLord, I want Jesus to walk with me.","note":"A spiritual of companionship through trouble, often sung at the bedside.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=I+want+Jesus+to+walk+with+me"},"rights":"pd","pd":"Traditional.","denom":[]},{"id":"prot-give-me-jesus","title":"Give Me Jesus","by":"Traditional spiritual","year":1880,"trad":["blackchurch","christian"],"type":"song","occasion":["dying","morning","peace"],"text":"In the morning when I rise,\nIn the morning when I rise,\nIn the morning when I rise,\nGive me Jesus.\n\nGive me Jesus,\nGive me Jesus,\nYou may have all this world,\nGive me Jesus.\n\nAnd when I come to die,\nAnd when I come to die,\nAnd when I come to die,\nGive me Jesus.","note":"A spiritual of simple longing, sung softly at the bedside and at homegoing services.","voice":"jenny","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Give+me+Jesus+in+the+morning+when+I+rise"},"rights":"pd","pd":"Traditional, nineteenth century.","denom":[]},{"id":"prot-let-us-break-bread","title":"Let Us Break Bread Together","by":"Traditional spiritual","year":1925,"trad":["blackchurch","christian"],"type":"song","occasion":["daily","gratitude"],"text":"Let us break bread together on our knees;\nLet us break bread together on our knees.\nWhen I fall on my knees,\nWith my face to the rising sun,\nO Lord, have mercy on me.\n\nLet us drink the cup together on our knees;\nLet us drink the cup together on our knees.\nWhen I fall on my knees,\nWith my face to the rising sun,\nO Lord, have mercy on me.","note":"A spiritual sung at communion in many traditions.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Let+us+break+bread+together+on+our+knees"},"rights":"pd","pd":"Traditional.","denom":[]},{"id":"prot-lord-i-want-to-be-a-christian","title":"Lord, I Want to Be a Christian","by":"Traditional spiritual","year":1907,"trad":["blackchurch","christian"],"type":"song","occasion":["daily","blessing"],"text":"Lord, I want to be a Christian in my heart, in my heart;\nLord, I want to be a Christian in my heart.\n\nLord, I want to be more loving in my heart, in my heart;\nLord, I want to be more loving in my heart.\n\nLord, I want to be like Jesus in my heart, in my heart;\nLord, I want to be like Jesus in my heart.","note":"A spiritual prayer of the heart, said to have grown from the Virginia revivals of the 1750s.","voice":"jenny","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Lord+I+want+to+be+a+Christian+in+my+heart"},"rights":"pd","pd":"Traditional.","denom":[]},{"id":"prot-every-time-i-feel-the-spirit","title":"Every Time I Feel the Spirit","by":"Traditional spiritual","year":1900,"trad":["blackchurch","pentecostal","christian"],"type":"song","occasion":["celebration","gratitude"],"text":"Every time I feel the spirit\nMoving in my heart, I will pray.\nYes, every time I feel the spirit\nMoving in my heart, I will pray.\n\nUpon the mountain my Lord spoke,\nOut of His mouth came fire and smoke.\nAll around me looks so shine,\nAsk my Lord if all was mine.","note":"A joyful spiritual of prayer and praise.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Every+time+I+feel+the+spirit"},"rights":"pd","pd":"Traditional.","denom":[]},{"id":"prot-soon-i-will-be-done","title":"Soon I Will Be Done","by":"Traditional spiritual","year":1900,"trad":["blackchurch","christian"],"type":"song","occasion":["dying","funeral","hope"],"text":"Soon I will be done with the troubles of the world,\nTroubles of the world, the troubles of the world.\nSoon I will be done with the troubles of the world;\nGoing home to live with God.\n\nI want to meet my mother,\nI want to meet my mother,\nI want to meet my mother,\nGoing home to live with God.","note":"A homegoing spiritual, sung at funerals in the Black church tradition.","voice":"jenny","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Soon+I+will+be+done+with+the+troubles+of+the+world"},"rights":"pd","pd":"Traditional.","denom":[]},{"id":"prot-jacobs-ladder","title":"We Are Climbing Jacob's Ladder","by":"Traditional spiritual","year":1867,"trad":["blackchurch","christian"],"type":"song","occasion":["hope","daily"],"text":"We are climbing Jacob's ladder,\nWe are climbing Jacob's ladder,\nWe are climbing Jacob's ladder,\nSoldiers of the cross.\n\nEvery round goes higher, higher,\nEvery round goes higher, higher,\nEvery round goes higher, higher,\nSoldiers of the cross.","note":"One of the oldest recorded spirituals, a song of steady upward faith.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=We+are+climbing+Jacob's+ladder"},"rights":"pd","pd":"Traditional, nineteenth century.","denom":[]},{"id":"prot-nobody-knows","title":"Nobody Knows the Trouble I've Seen","by":"Traditional spiritual","year":1867,"trad":["blackchurch","christian"],"type":"song","occasion":["grief","comfort"],"text":"Nobody knows the trouble I've seen,\nNobody knows but Jesus.\nNobody knows the trouble I've seen,\nGlory, hallelujah!\n\nSometimes I'm up, sometimes I'm down,\nOh, yes, Lord;\nSometimes I'm almost to the ground,\nOh, yes, Lord.","note":"A spiritual that names sorrow and ends in glory.","voice":"jenny","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Nobody+knows+the+trouble+I've+seen"},"rights":"pd","pd":"Traditional, printed by 1867.","denom":[]},{"id":"prot-lift-every-voice","title":"Lift Every Voice and Sing (from)","by":"James Weldon Johnson","year":1900,"trad":["blackchurch","christian"],"type":"hymn","occasion":["celebration","hope","gratitude"],"text":"Lift every voice and sing\nTill earth and heaven ring,\nRing with the harmonies of Liberty;\nLet our rejoicing rise\nHigh as the listening skies,\nLet it resound loud as the rolling sea.\nSing a song full of the faith that the dark past has taught us,\nSing a song full of the hope that the present has brought us;\nFacing the rising sun of our new day begun,\nLet us march on till victory is won.","note":"Written for Lincoln's birthday in 1900 and sung in Black churches as a hymn of faith and hope.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=Lift+every+voice+and+sing"},"rights":"pd","pd":"Written 1900; published 1900 and 1921.","denom":[]},{"id":"prot-go-down-death","title":"Go Down Death: A Funeral Sermon (from)","by":"James Weldon Johnson","year":1927,"trad":["blackchurch","christian"],"type":"poem","occasion":["funeral","grief","comfort"],"text":"Weep not, weep not,\nShe is not dead;\nShe's resting in the bosom of Jesus.\nHeart-broken husband, weep no more;\nGrief-stricken son, weep no more;\nLeft-lonesome daughter, weep no more;\nShe's only just gone home.","note":"The opening of Johnson's poem in the voice of a Black preacher at a funeral, from God's Trombones (1927).","voice":"jenny","source":{"name":"James Weldon Johnson, God's Trombones (1927)","url":"https://www.gutenberg.org/ebooks/search/?query=god%27s+trombones"},"rights":"pd","pd":"Published 1927; US public domain since 2023.","denom":[]},{"id":"prot-stand-by-me","title":"Stand By Me (from)","by":"Charles Albert Tindley","year":1905,"trad":["blackchurch","methodist","christian"],"type":"hymn","occasion":["comfort","healing","dying"],"text":"When the storms of life are raging,\nStand by me;\nWhen the storms of life are raging,\nStand by me.\nWhen the world is tossing me\nLike a ship upon the sea,\nThou who rulest wind and water,\nStand by me.","note":"By the Philadelphia Methodist pastor called the prince of preachers, a founder of Black gospel song.","voice":"brian","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=When+the+storms+of+life+are+raging+stand+by+me"},"rights":"pd","pd":"Published 1905; Tindley died 1933.","denom":[]},{"id":"prot-understand-it-better","title":"We'll Understand It Better By and By (from)","by":"Charles Albert Tindley","year":1905,"trad":["blackchurch","methodist","christian"],"type":"hymn","occasion":["grief","funeral","hope"],"text":"By and by, when the morning comes,\nWhen the saints of God are gathered home,\nWe'll tell the story how we've overcome,\nFor we'll understand it better by and by.","note":"The refrain of Tindley's hymn for seasons when life does not make sense; sung at funerals.","voice":"jenny","source":{"name":"Hymnary.org, texts and printings","url":"https://hymnary.org/search?qu=We'll+understand+it+better+by+and+by"},"rights":"pd","pd":"Published 1905; Tindley died 1933.","denom":[]},{"id":"prot-wake-awake","title":"Wake, Awake, for Night Is Flying","by":"Philipp Nicolai","tr":"Catherine Winkworth","year":1599,"trad":["lutheran","christian"],"type":"hymn","occasion":["wedding","hope","season"],"text":"Wake, awake, for night is flying:\nThe watchmen on the heights are crying,\nAwake, Jerusalem, arise!\nMidnight's solemn hour is tolling,\nHis chariot wheels are nearer rolling,\nHe comes; prepare, ye virgins wise.\nRise up with willing feet,\nGo forth, the Bridegroom meet:\nAlleluia!\nBear through the night your well trimmed light,\nSpeed forth to join the marriage rite.\n\nZion hears the watchmen singing,\nAnd all her heart with joy is springing,\nShe wakes, she rises from her gloom;\nForth her Bridegroom comes, all-glorious,\nThe strong in grace, in truth victorious;\nHer Star is risen, her Light is come!\nAll hail, Thou precious One!\nLord Jesus, God's dear Son!\nAlleluia!\nThe joyful call we answer all,\nAnd follow to the nuptial hall.\n\nLamb of God, the heavens adore Thee,\nAnd men and angels sing before Thee,\nWith harp and cymbal's clearest tone.\nBy the pearly gates in wonder\nWe stand, and swell the voice of thunder,\nThat echoes round Thy dazzling throne.\nTo mortal eyes and ears\nWhat glory now appears!\nAlleluia!\nWe raise the song, we swell the throng,\nTo praise Thee ages all along.","note":"The King of Chorales, a wedding feast hymn on the parable of the wise bridesmaids, sung in Advent.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Nicolai died 1608; Winkworth translation 1858.","denom":[]},{"id":"prot-all-glory-be","title":"All Glory Be to Thee, Most High","by":"Nicolaus Decius","year":1526,"trad":["lutheran","christian"],"type":"hymn","occasion":["gratitude","celebration"],"text":"All glory be to Thee, Most High,\nTo Thee all adoration!\nIn grace and truth Thou drawest nigh\nTo offer us salvation.\nThou showest Thy good will toward men,\nAnd peace shall reign on earth again;\nWe praise Thy Name forever.\n\nWe praise, we worship Thee, we trust,\nAnd give Thee thanks forever,\nO Father, for Thy rule is just\nAnd wise, and changes never.\nThy hand almighty o'er us reigns,\nThou doest what Thy will ordains;\n'Tis well for us Thou rulest.\n\nO Jesus Christ, our God and Lord,\nSon of the Heavenly Father,\nO Thou, who hast our peace restored,\nThe straying sheep dost gather,\nThou Lamb of God, to Thee on high\nOut of the depths we sinners cry:\nHave mercy on us, Jesus!\n\nO Holy Ghost, Thou precious gift,\nThou Comforter, unfailing,\nFrom Satan's snares our souls uplift,\nAnd let Thy power, availing,\nAvert our woes and calm our dread;\nFor us the Saviour's blood was shed,\nWe trust in Thee to save us!","note":"A Lutheran Gloria in hymn form, sung since the Reformation.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Decius died 1541; English printed 1930.","denom":[]},{"id":"prot-let-me-be-thine-forever","title":"Let Me Be Thine Forever","by":"Nicolaus Selnecker","year":1572,"trad":["lutheran","christian"],"type":"hymn","occasion":["daily","blessing"],"text":"Let me be Thine forever,\nMy gracious God and Lord,\nMay I forsake Thee never,\nNor wander from Thy Word:\nPreserve me from the mazes\nOf error and distrust,\nAnd I shall sing Thy praises\nForever with the just.\n\nLord Jesus, bounteous Giver\nOf light and life divine,\nThou didst my soul deliver,\nTo Thee I all resign:\nThou hast in mercy bought me\nWith blood and bitter pain;\nLet me, since Thou hast sought me,\nEternal life obtain.\n\nO Holy Ghost, who pourest\nSweet peace into my heart,\nAnd who my soul restorest,\nLet not Thy grace depart.\nAnd while His Name confessing\nWhom I by faith have known,\nGrant me Thy constant blessing,\nMake me for aye Thine own.","note":"A Lutheran confirmation and commitment hymn.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Selnecker died 1592; English printed 1930.","denom":[]},{"id":"prot-be-not-dismayed","title":"Be Not Dismayed, Thou Little Flock","by":"Johann Michael Altenburg","year":1631,"trad":["lutheran","christian"],"type":"hymn","occasion":["comfort","hope"],"text":"Be not dismayed, thou little flock,\nAlthough the foe's fierce battle shock\nLoud on all sides assail thee.\nThough o'er thy fall they laugh secure,\nTheir triumph cannot long endure,\nLet not thy courage fail thee.\n\nThy cause is God's, go at His call,\nAnd to His hand commit thine all;\nFear thou no ill impending;\nHis Gideon shall arise for thee,\nGod's Word and people manfully\nIn God's own time defending.\n\nOur hope is sure in Jesus' might;\nAgainst themselves the godless fight,\nThemselves, not us, distressing;\nShame and contempt their lot shall be;\nGod is with us, with Him are we;\nTo us belongs His blessing.","note":"A hymn of courage from the Thirty Years' War.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Altenburg died 1640; English printed 1930.","denom":[]},{"id":"prot-all-my-heart-this-night","title":"All My Heart This Night Rejoices","by":"Paul Gerhardt","tr":"Catherine Winkworth","year":1656,"trad":["lutheran","christian"],"type":"hymn","occasion":["season","celebration","birth"],"text":"All my heart this night rejoices,\nAs I hear,\nFar and near,\nSweetest angel voices:\n\"Christ is born,\" their choirs are singing,\nTill the air\nEverywhere\nNow with joy is ringing.\n\nCome and banish all your sadness,\nOne and all,\nGreat and small,\nCome with songs of gladness;\nLove Him who with love is yearning;\nHail the star\nThat from far\nBright with hope is burning.\n\nHither come, ye heavy-hearted,\nWho for sin,\nDeep within,\nLong and sore have smarted;\nFor the poisoned wounds you're feeling\nHelp is near,\nOne is here\nMighty for their healing.\n\nFaithfully Thee, Lord, I'll cherish,\nLive to Thee,\nAnd with Thee\nDying, shall not perish,\nBut shall dwell with Thee forever,\nFar on high,\nIn the joy\nThat can alter never.","note":"Gerhardt's Christmas hymn of joy.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Gerhardt died 1676; Winkworth translation 1858.","denom":[]},{"id":"prot-thee-will-i-love","title":"Thee Will I Love, My Strength, My Tower","by":"Johann Scheffler","tr":"Catherine Winkworth","year":1657,"trad":["lutheran","christian"],"type":"hymn","occasion":["daily","wedding"],"text":"Thee will I love, my Strength, my Tower,\nThee will I love, my Joy, my Crown;\nThee will I love with all my power,\nIn all Thy works, and Thee alone;\nThee will I love, till Thy pure fire\nFill all my soul with chaste desire.\n\nI thank Thee, uncreated Sun,\nThat Thy bright beams on me have shined;\nI thank Thee, who hast overthrown\nMy foes, and healed my wounded mind;\nI thank Thee, whose enlivening voice\nBids my freed heart in Thee rejoice.\n\nUphold me in the doubtful race,\nNor suffer me again to stray;\nStrengthen my feet with steady pace\nStill to press forward in Thy way;\nThat all my powers, with all their might,\nIn Thy sole glory may unite.\n\nThee will I love, my Joy, my Crown;\nThee will I love, my Lord, my God;\nThee love beneath Thy smile or frown,\nBeneath Thy scepter or Thy rod.\nWhat though my flesh and heart decay?\nThee shall I love in endless day.","note":"A hymn of devotion by the Silesian poet known as Angelus Silesius.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Scheffler died 1677; Winkworth translation 1858.","denom":[]},{"id":"prot-source-of-calm-repose","title":"O Jesus, Source of Calm Repose","by":"Johann Anastasius Freylinghausen","tr":"John Wesley","year":1704,"trad":["lutheran","methodist","christian"],"type":"hymn","occasion":["peace","comfort"],"text":"O Jesus, Source of calm repose,\nThy like no man nor angel knows,\nFairest among ten thousand fair!\nE'en those whom death's sad fetters bound,\nWhom thickest darkness compassed round,\nFind light and life, if Thou appear.\n\nRenew Thine image, Lord, in me,\nLowly and gentle may I be;\nNo charms but these to Thee are dear;\nNo anger may'st Thou ever find,\nNo pride, in my unruffled mind,\nBut faith, and heaven-born peace, be there.\n\nA patient, a victorious mind,\nThat life and all things casts behind,\nSprings forth obedient to Thy call,\nA heart that no desire can move,\nBut still to praise, believe, and love,\nGive me, my Lord, my Life, my All!","note":"A hymn from the Halle pietists, in John Wesley's English.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Freylinghausen died 1739; Wesley translation 1737.","denom":[]},{"id":"prot-thou-hidden-love","title":"Thou Hidden Love of God","by":"Gerhard Tersteegen","tr":"John Wesley","year":1729,"trad":["presbyterian","methodist","christian"],"denom":["reformed"],"type":"hymn","occasion":["peace","daily"],"text":"Thou hidden love of God, whose height,\nWhose depth unfathomed no man knows,\nI see from far Thy beauteous light,\nInly I sigh for Thy repose:\nMy heart is pained, nor can it be\nAt rest; till it find rest in Thee.\n\nIs there a thing beneath the sun\nThat strives with Thee my heart to share?\nAh! tear it thence, and reign alone,\nThe Lord of every motion there.\nThen shall my heart from earth be free,\nWhen it hath found repose in Thee.\n\nO hide this self from me, that I\nNo more, but Christ in me, may live!\nMy base affections crucify,\nNor let one favorite sin survive;\nIn all things nothing may I see,\nNothing desire, or seek, but Thee.\n\nEach moment draw from earth away\nMy heart that lowly waits Thy call!\nSpeak to my inmost soul, and say:\n\"I am thy Love, thy God, thy All!\"\nTo feel Thy power, to hear Thy voice,\nTo taste Thy love, be all my choice!","note":"A hymn of the inner life by the Reformed mystic Tersteegen, translated by John Wesley in Georgia.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Tersteegen died 1769; Wesley translation 1736."},{"id":"prot-we-plow-the-fields","title":"We Plow the Fields and Scatter","by":"Matthias Claudius","tr":"Jane Montgomery Campbell","year":1782,"trad":["lutheran","christian"],"type":"hymn","occasion":["gratitude","nature","season"],"text":"We plow the fields and scatter\nThe good seed on the land,\nBut it is fed and watered\nBy God's almighty hand;\nHe sends the snow in winter,\nThe warmth to swell the grain,\nThe breezes and the sunshine,\nAnd soft, refreshing rain.\n\nHe only is the Maker\nOf all things near and far;\nHe paints the wayside flower,\nHe lights the evening star;\nThe winds and waves obey Him,\nBy Him the birds are fed;\nMuch more to us, His children,\nHe gives our daily bread.\n\nWe thank Thee, then, O Father,\nFor all things bright and good,\nThe seedtime and the harvest,\nOur life, our health, our food;\nNo gifts have we to offer\nFor all Thy love imparts,\nBut that which Thou desirest,\nOur humble, thankful hearts.","note":"The harvest thanksgiving hymn, from a German peasant song.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Claudius died 1815; Campbell translation 1861.","denom":[]},{"id":"prot-o-happy-home","title":"O Happy Home","by":"Carl Johann Philipp Spitta","year":1833,"trad":["lutheran","christian"],"type":"hymn","occasion":["home","wedding","blessing"],"text":"O happy home, where Thou art loved the dearest,\nThou loving Friend and Saviour of our race,\nAnd where among the guests there never cometh\nOne who can hold such high and honored place!\n\nO happy home, where two, in heart united,\nIn holy faith and blessed hope are one,\nWhom death a little while alone divideth,\nAnd cannot end the union here begun!\n\nO happy home, whose little ones are given\nEarly to Thee in humble faith and prayer,\nTo Thee, their Friend, who from the heights of heaven\nGuides them, and guards with more than mother's care.\n\nO happy home, where each one serves Thee lowly,\nWhatever his appointed work may be,\nTill every common task seems great and holy,\nWhen it is done, O Lord, as unto Thee!\n\nO happy home, where Thou art not forgotten\nWhen joy is overflowing, full and free,\nO happy home, where every wounded spirit\nIs brought, Physician, Comforter, to Thee.\n\nAnd when at last all earthly toil is ended,\nAll meet Thee in the blessed home above,\nFrom whence Thou camest, where Thou hast ascended,\nThine everlasting home of peace and love.","note":"A hymn for the blessing of a home and for weddings.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Spitta died 1859; English printed 1930.","denom":[]},{"id":"prot-our-father-merciful","title":"Our Father, Merciful and Good","by":"Olavus Petri","year":1530,"trad":["lutheran","christian"],"denom":["swedish"],"type":"hymn","occasion":["daily","comfort"],"text":"Our Father, merciful and good,\nWho dost to Thee invite us,\nO cleanse us in our Saviour's blood,\nAnd to Thyself unite us!\nSend unto us Thy Holy Word,\nAnd let it guide us ever;\nThen in this world of darkness, Lord,\nShall naught from Thee us sever:\nGrant us, O Lord, this favor!\n\nO God and man, Christ Jesus blest!\nOur sorrows Thou didst carry.\nOur wants and cares Thou knowest best,\nFor Thou with us didst tarry.\nO Jesus Christ, our Brother dear,\nTo us and every nation\nThy Spirit send, let Him draw near\nWith truth and consolation,\nThat we may see salvation.\n\nCome, Holy Ghost, Thy grace impart,\nTear Satan's snares asunder.\nThe Word of God keep in our heart,\nThat we its truth may ponder.\nThen, sanctified, for evermore,\nIn Christ alone confiding,\nWe'll sing His praise and Him adore,\nHis precious Word us guiding\nTo heavenly joys abiding.","note":"A hymn by the reformer of Sweden, sung in Swedish Lutheran churches.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Petri died 1552; English printed 1930."},{"id":"prot-again-thy-glorious-sun","title":"Again Thy Glorious Sun Doth Rise","by":"Johan Olof Wallin","year":1816,"trad":["lutheran","christian"],"denom":["swedish"],"type":"hymn","occasion":["morning","daily"],"text":"Again Thy glorious sun doth rise,\nI praise Thee, O my Lord;\nWith courage, strength, and hope renewed,\nI touch the joyful chord.\n\nOn good and evil, Lord, Thy sun\nIs rising as on me;\nLet me in patience and in love\nSeek thus to be like Thee.\n\nMay I in virtue and in faith,\nAnd with Thy gifts content,\nRejoice beneath Thy covering wings,\nEach day in mercy sent.\n\nSafe with Thy counsel in my work,\nThee, Lord, I'll keep in view,\nAnd feel that still Thy bounteous grace\nIs every morning new.","note":"A Swedish morning hymn by the great hymn writer of the Church of Sweden.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Wallin died 1839; English printed 1930."},{"id":"prot-jerusalem-jerusalem","title":"Jerusalem, Jerusalem","by":"Lina Sandell Berg","year":1870,"trad":["lutheran","christian"],"denom":["swedish"],"type":"hymn","occasion":["funeral","hope"],"text":"Jerusalem, Jerusalem,\nThou city ever blest,\nWithin thy portals first I find\nMy safety, peace, and rest.\nHere dangers always threaten me,\nMy days in strife are spent,\nAnd labor, sorrow, worry, grief,\nI find at best their strength.\n\nNo wonder, then, that I do long,\nO blessed home, for thee,\nWhere I shall find a resting-place,\nFrom sin and sorrow free;\nWhere tears and weeping are no more,\nNor death, nor pain, nor night,\nFor former things are passed away,\nAnd darkness turned to light.\n\nNow all for me has lost its charm\nWhich by the world is praised,\nSince on the cross, through faith, I saw\nMy Saviour Jesus raised;\nMy goal is fixed, one thing I ask,\nWhate'er the cost may be,\nJerusalem, Jerusalem,\nSoon to arrive in thee.\n\nCarolina Vilhelmina (Sandell) Berg (1832-1903).","note":"A song of the heavenly home by Sweden's beloved hymn writer, sung at Scandinavian Lutheran funerals.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Sandell died 1903; English printed 1930."},{"id":"prot-the-sun-arises-now","title":"The Sun Arises Now","by":"Thomas Kingo","year":1674,"trad":["lutheran","christian"],"denom":["danish"],"type":"hymn","occasion":["morning","daily"],"text":"The sun arises now\nIn light and glory,\nAnd gilds the rugged brow\nOf mountains hoary;\nBe glad, my soul, and lift\nThy voice in singing\nTo God from earth below,\nThy heart with joy aglow\nAnd praises ringing.\n\nLike countless grains of sand,\nBeyond all measure,\nAnd wide as sea and land\nIs heaven's treasure\nOf grace which God anew\nEach day bestoweth,\nAnd which, like pouring rain,\nInto my soul again\nEach morning floweth.\n\nKeep Thou my soul today\nFrom sin and blindness;\nSurround me on my way\nWith loving-kindness,\nAnd fill my heart, O God,\nWith joy from heaven;\nI then shall ask no more\nThan what Thou hast of yore\nIn wisdom given.\n\nThou knowest best my needs,\nMy sighs Thou heedest;\nThy hand Thy children feeds,\nThine own Thou leadest;\nWhat should I more desire,\nWith Thee deciding\nThe course that I must take\nThan follow in the wake\nWhere Thou art guiding?","note":"A Danish morning hymn by the poet bishop Thomas Kingo.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Kingo died 1703; English printed 1930."},{"id":"prot-behold-a-host","title":"Behold a Host, Arrayed in White","by":"Hans Adolph Brorson","year":1763,"trad":["lutheran","christian"],"denom":["norwegian","danish"],"type":"hymn","occasion":["funeral","hope","grief"],"text":"Behold a host, arrayed in white,\nLike thousand snow-clad mountains bright,\nWith palms they stand, who are this band\nBefore the throne of light?\nLo, these are they, of glorious fame,\nWho from the great affliction came,\nAnd in the flood of Jesus' blood\nAre cleansed from guilt and blame;\nNow gathered in the holy place\nTheir voices they in worship raise,\nTheir anthems swell where God doth dwell\n'Mid angels' songs of praise.\n\nDespised and scorned, they sojourned here,\nBut now, how glorious they appear!\nThese martyrs stand a priestly band,\nGod's throne forever near.\nSo oft, in troubled days gone by,\nIn anguish they would weep and sigh;\nAt home above, the God of love\nThe tears of all shall dry.\nThey now enjoy their Sabbath rest,\nThe paschal banquet of the blest;\nThe Lamb, their Lord, at festal board\nHimself is host and guest.\n\nThen hail, ye mighty legions, yea,\nAll hail! now safe and blest for aye;\nAnd praise the Lord, who with His Word\nSustained you on the way.\nYe did the joys of earth disdain,\nYe toiled and sowed in tears and pain;\nFarewell, now bring your sheaves, and sing\nSalvation's glad refrain.\nSwing high your palms, lift up your song,\nYea, make it myriad voices strong:\nEternally shall praise to Thee,\nGod, and the Lamb, belong!","note":"Brorson's vision of the saints in glory, sung at Norwegian and Danish Lutheran funerals.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Brorson died 1764; English printed 1930."},{"id":"prot-holy-spirit-come-with-light","title":"Holy Spirit, Come with Light","by":"Nikolai Grundtvig","year":1830,"trad":["lutheran","christian"],"denom":["danish"],"type":"hymn","occasion":["blessing","season"],"text":"Holy Spirit, come with light,\nBreak the dark and gloomy night\nWith Thy day unending;\nHelp us with a joyful lay\nGreet the Lord's triumphant day\nNow with might ascending.\n\nComforter, so wondrous kind,\nNoble Guest of heart and mind,\nFix in us Thy dwelling.\nGive us peace in storm and strife,\nFill each weary heart and life\nWith Thy joy excelling.\n\nMake salvation clear to us,\nWho, despite our sin and cross,\nAre in Thee confiding.\nLest our life be void and vain,\nWith Thy light and love remain\nAye in us abiding.\n\nRaise or bow us with Thine arm,\nBreak temptation's evil charm,\nClear our clouded vision.\nFill our hearts with longings new,\nCleanse us with Thy morning dew,\nTears of deep contrition.\n\nThou who givest life and breath,\nLet our hope in sight of death\nBlossom bright and vernal;\nAnd above the silent tomb\nLet the Easter lilies bloom,\nSigns of life eternal.","note":"A Pentecost hymn by the Danish pastor and poet Grundtvig.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Grundtvig died 1872; English printed 1930."},{"id":"prot-before-thee-god","title":"Before Thee, God, Who Knowest All","by":"Magnus Brorstrup Landstad","year":1861,"trad":["lutheran","christian"],"denom":["norwegian"],"type":"hymn","occasion":["forgiveness","peace"],"text":"Before Thee, God, who knowest all,\nWith grief and shame I prostrate fall;\nI see my sins against Thee, Lord,\nThe sins of thought, of deed, and word,\nThey press me sore, I cry to Thee;\nO God, be merciful to me!\n\nO Lord, My God, to Thee I pray:\nO cast me not in wrath away,\nLet Thy good Spirit ne'er depart,\nBut let Him draw to Thee my heart,\nThat truly penitent I be;\nO God, be merciful to me!\n\nO Jesus, let Thy precious blood\nBe to my soul a cleansing flood;\nTurn not, O Lord, Thy guest away,\nBut grant that justified I may\nGo to my house with peace from Thee;\nO God, be merciful to me!","note":"A Norwegian hymn of confession and peace.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Landstad died 1880; English printed 1930."},{"id":"prot-rise-ye-children","title":"Rise, Ye Children of Salvation","by":"Justus Falckner","year":1697,"trad":["lutheran","christian"],"type":"hymn","occasion":["celebration","hope"],"text":"Rise, ye children of salvation,\nAll who cleave to Christ, the Head!\nWake, arise, O mighty nation,\nEre the foe on Zion tread:\nHe draws nigh, and would defy\nAll the hosts of God Most High.\n\nSaints and heroes, long before us,\nFirmly on this ground have stood;\nSee their banner waving o'er us,\nConquerors through the Saviour's blood!\nGround we hold whereon of old\nFought the faithful and the bold.\n\nFighting, we shall be victorious\nBy the blood of Christ our Lord;\nOn our foreheads, bright and glorious,\nShines the witness of His Word;\nSpear and shield on battlefield,\nHis great Name; we cannot yield.\n\nWhen His servants stand before Him,\nEach receiving his reward,\nWhen His saints in light adore Him,\nGiving glory to the Lord,\n\"Victory!\" our song shall be,\nLike the thunder of the sea.","note":"By the first Lutheran pastor ordained in America.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Falckner died 1723; English printed 1930.","denom":[]},{"id":"prot-oer-jerusalem","title":"O'er Jerusalem Thou Weepest","by":"Anna Hoppe","year":1919,"trad":["lutheran","christian"],"type":"hymn","occasion":["grief","comfort"],"text":"O'er Jerusalem Thou weepest\nIn compassion, dearest Lord!\nLove divine, of love the deepest,\nO'er Thine erring Israel poured,\nCrieth out in bitter moan,\n\"O loved city, hadst thou known\nThis thy day of visitation,\nThou wouldst not reject salvation.\"\n\nBy the love Thy tears are telling,\nO Thou Lamb for sinners slain,\nMake my heart Thy temple dwelling,\nPurged from every guilty stain!\nO forgive, forgive my sin!\nCleanse me, cleanse me, Lord, within!\nI am Thine since Thou hast sought me,\nSince Thy precious blood hath bought me.\n\nO Thou Lord of my salvation,\nGrant my soul Thy blood-bought peace.\nBy the tears of lamentation\nBid my faith and love increase.\nGrant me grace to love Thy Word,\nGrace to keep the message heard,\nGrace to own Thee as my Treasure,\nGrace to love Thee without measure.","note":"By a Milwaukee Lutheran hymn writer, on the tears of Jesus.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Published 1919.","denom":[]},{"id":"prot-day-is-dying","title":"Day Is Dying in the West","by":"Mary Artemisia Lathbury","year":1877,"trad":["methodist","christian"],"type":"hymn","occasion":["evening","nature","peace"],"text":"Day is dying in the west;\nHeaven is touching earth with rest:\nWait and worship while the night\nSets her evening lamps alight\nThrough all the sky.\n\nRefrain:\nHoly, holy, holy, Lord God of Hosts!\nHeaven and earth are full of Thee!\nHeaven and earth are praising Thee,\nO Lord Most High!\n\nLord of life, beneath the dome\nOf the universe, Thy home,\nGather us who seek Thy face\nTo the fold of Thy embrace,\nFor Thou art nigh.\n\nWhile the deepening shadows fall,\nHeart of Love, enfold us all;\nThrough the glory and the grace\nOf the stars that veil Thy face,\nOur hearts ascend.\n\nWhen forever from our sight\nPass the stars, the day, the night,\nLord of angels, on our eyes\nLet eternal morning rise,\nAnd shadows end.","note":"An evening hymn written for the Methodist Chautauqua summer assembly.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Published 1877 and 1890; Lathbury died 1913.","denom":[]},{"id":"prot-where-cross-the-crowded-ways","title":"Where Cross the Crowded Ways of Life","by":"Frank Mason North","year":1905,"trad":["methodist","christian"],"type":"hymn","occasion":["daily","blessing"],"text":"Where cross the crowded ways of life,\nWhere sound the cries of race and clan,\nAbove the noise of selfish strife,\nWe hear Thy voice, O Son of man!\n\nIn haunts of wretchedness and need,\nOn shadowed thresholds dark with fears,\nFrom paths where hide the lures of greed,\nWe catch the vision of Thy tears.\n\nFrom tender childhood's helplessness,\nFrom woman's grief, man's burdened toil,\nFrom famished souls, from sorrow's stress,\nThy heart has never known recoil.\n\nThe cup of water given for Thee\nStill holds the freshness of Thy grace;\nYet long these multitudes to see\nThe sweet compassion of Thy face.\n\nO Master, from the mountain-side,\nMake haste to heal these hearts of pain,\nAmong these restless throngs abide,\nO tread the city's streets again,\n\nTill sons of men shall learn Thy love\nAnd follow where Thy feet have trod;\nTill glorious from Thy heaven above\nShall come the city of our God.","note":"A Methodist hymn of service in the city.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Published 1905.","denom":[]},{"id":"prot-all-hail-the-power","title":"All Hail the Power of Jesus' Name","by":"Edward Perronet","year":1779,"trad":["methodist","ucc","christian"],"type":"hymn","occasion":["celebration","gratitude"],"text":"All hail the power of Jesus' Name!\nLet angels prostrate fall;\nBring forth the royal diadem,\nAnd crown Him Lord of all.\n\nYe seed of Israel's chosen race,\nYe ransomed from the fall,\nHail Him, who saves you by His grace,\nAnd crown Him Lord of all.\n\nHail Him, ye heirs of David's line,\nWhom David Lord did call;\nThe Lord incarnate, Man divine,\nAnd crown Him Lord of all.\n\nSinners, whose love can ne'er forget\nThe wormwood and the gall;\nGo, spread your trophies at His feet,\nAnd crown Him Lord of all.\n\nLet every kindred, every tribe,\nOn this terrestrial ball\nTo Him all majesty ascribe,\nAnd crown Him Lord of all.\n\nO that with yonder sacred throng\nWe at His feet may fall!\nWe'll join the everlasting song,\nAnd crown Him Lord of all.","note":"The Coronation hymn by a preacher who traveled with the Wesleys.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Perronet died 1792.","denom":[]},{"id":"prot-prayer-is-the-souls-desire","title":"Prayer Is the Soul's Sincere Desire","by":"James Montgomery","year":1818,"trad":["moravian","christian"],"type":"hymn","occasion":["daily","peace","dying"],"text":"Prayer is the soul's sincere desire,\nUttered or unexpressed;\nThe motion of a hidden fire\nThat trembles in the breast.\n\nPrayer is the simplest form of speech\nThat infant lips can try;\nPrayer the sublimest strains that reach\nThe majesty on high.\n\nPrayer is the contrite sinner's voice,\nReturning from his ways;\nWhile angels in their songs rejoice\nAnd cry, \"Behold, he prays!\"\n\nPrayer is the Christian's vital breath,\nThe Christian's native air;\nHis watchword at the gates of death;\nHe enters heaven with prayer.\n\nO Thou, by whom we come to God,\nThe Life, the Truth, the Way,\nThe paths of prayer Thyself hast trod:\nLord, teach us how to pray!","note":"By the Moravian poet James Montgomery, a hymn about prayer itself.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Montgomery died 1854.","denom":[]},{"id":"prot-father-of-mercies","title":"Father of Mercies, in Thy Word","by":"Anne Steele","year":1760,"trad":["baptist","christian"],"type":"hymn","occasion":["daily","comfort"],"text":"Father of Mercies, in Thy Word\nWhat endless glory shines!\nForever be Thy Name adored\nFor these celestial lines.\n\nHere the Redeemer's welcome voice\nSpreads heavenly peace around;\nAnd life and everlasting joys\nAttend the blissful sound.\n\nO may these heavenly pages be\nMy ever dear delight;\nAnd still new beauties may I see,\nAnd still increasing light.\n\nDivine Instructor, gracious Lord,\nBe Thou forever near;\nTeach me to love Thy sacred Word,\nAnd view my Saviour there.","note":"By the English Baptist hymn writer Anne Steele, a hymn of love for scripture.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Steele died 1778.","denom":[]},{"id":"prot-steal-awhile-away","title":"I Love to Steal Awhile Away","by":"Phoebe Hinsdale Brown","year":1818,"trad":["ucc","christian"],"denom":["congregational"],"type":"hymn","occasion":["evening","peace","nature"],"text":"I love to steal awhile away\nFrom every cumbering care,\nAnd spend the hour of setting day\nIn humble, grateful prayer.\n\nI love in solitude to shed\nThe penitential tear,\nAnd all His promises to plead\nWhere none but God can hear.\n\nI love to think of mercies past,\nAnd future good implore,\nAnd all my cares and sorrows cast\nOn Him whom I adore.\n\nI love by faith to take a view\nOf brighter scenes in heaven;\nThe prospect doth my strength renew,\nWhile here by tempests driven.\n\nThus when life's toilsome day is o'er,\nMay its departing ray\nBe calm as this impressive hour\nAnd lead to endless day.","note":"Written by a New England mother who prayed at twilight in a quiet grove.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Brown died 1861."},{"id":"prot-that-sweet-story-of-old","title":"I Think, When I Read That Sweet Story of Old","by":"Jemima Luke","year":1841,"trad":["ucc","christian"],"denom":["congregational"],"type":"hymn","occasion":["birth","blessing"],"text":"I think, when I read that sweet story of old,\nWhen Jesus was here among men,\nHow He called little children as lambs to His fold,\nI should like to have been with them then.\n\nI wish that His hand had been placed on my head,\nThat His arm had been thrown around me,\nAnd that I might have seen His kind look when He said,\n\"Let the little ones come unto Me.\"\n\nYet still to His footstool in prayer I may go,\nAnd ask for a share in His love;\nAnd if only I earnestly seek Him below,\nI shall see Him and hear Him above.\n\nIn that beautiful place He has gone to prepare\nFor all who are washed and forgiven,\nFull many dear children are gathering there,\n\"For of such is the kingdom of heaven\"\n\nBut thousands and thousands who wander and fall\nNever heard of that heavenly home:\nI should like them to know there is room for them all,\nAnd that Jesus has bid them to come.\n\nAnd O how I long for that glorious time,\nThe sweetest and brightest and best,\nWhen the dear little children of every clime\nShall crowd to His arms and be blest!","note":"A children's hymn by an English Congregationalist, on Jesus blessing the children.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Luke died 1906."},{"id":"prot-i-love-thy-zion","title":"I Love Thy Zion, Lord","by":"Timothy Dwight","year":1800,"trad":["ucc","christian"],"denom":["congregational"],"type":"hymn","occasion":["gratitude","home"],"text":"I love Thy Zion, Lord,\nThe house of Thine abode;\nThe Church our blest Redeemer saved\nWith His own precious blood.\n\nI love Thy Church, O God;\nHer walls before Thee stand,\nDear as the apple of Thine eye,\nAnd graven on Thy hand.\n\nFor her my tears shall fall;\nFor her my prayers ascend:\nTo her my cares and toil be given,\nTill toils and cares shall end.\n\nBeyond my highest joy\nI prize her heavenly ways,\nHer sweet communion, solemn vows,\nHer hymns of love and praise.\n\nJesus, Thou Friend divine,\nOur Saviour and our King,\nThy hand from every snare and foe\nShall great deliverance bring.\n\nSure as Thy truth shall last,\nTo Zion shall be given\nThe brightest glories earth can yield,\nAnd brighter bliss of heaven.","note":"By the Congregational president of Yale; the oldest American hymn still widely sung.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Dwight died 1817."},{"id":"prot-jesus-saviour-pilot-me","title":"Jesus, Saviour, Pilot Me","by":"Edward Hopper","year":1871,"trad":["presbyterian","christian"],"type":"hymn","occasion":["dying","comfort","funeral"],"text":"Jesus, Saviour, pilot me\nOver life's tempestuous sea;\nUnknown waves before me roll,\nHiding rock and treacherous shoal;\nChart and compass came from Thee:\nJesus, Saviour, pilot me.\n\nAs a mother stills her child,\nThou canst hush the ocean wild;\nBoisterous waves obey Thy will\nWhen Thou say'st to them, \"Be still!\"\nWondrous Sovereign of the sea,\nJesus, Saviour, pilot me.\n\nWhen at last I near the shore,\nAnd the fearful breakers roar\n'Twixt me and the peaceful rest,\nThen, while leaning on Thy breast,\nMay I hear Thee say to me,\n\"Fear not, I will pilot thee.\"","note":"Written by a Presbyterian pastor to sailors in New York harbor; its last stanza is a prayer for the crossing.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Hopper died 1888.","denom":[]},{"id":"prot-we-would-see-jesus","title":"We Would See Jesus","by":"Anna Bartlett Warner","year":1851,"trad":["presbyterian","christian"],"type":"hymn","occasion":["dying","hope"],"text":"We would see Jesus, for the shadows lengthen\nAcross this little landscape of our life;\nWe would see Jesus, our weak faith to strengthen\nFor the last weariness, the final strife.\n\nWe would see Jesus, the great Rock-foundation\nWhereon our feet were set by sovereign grace:\nNor life nor death, with all their agitation,\nCan thence remove us, if we see His face.\n\nWe would see Jesus: other lights are paling,\nWhich for long years we have rejoiced to see;\nThe blessings of our pilgrimage are failing:\nWe would not mourn them, for we go to Thee.\n\nWe would see Jesus: this is all we're needing;\nStrength, joy, and willingness come with the sight;\nWe would see Jesus, dying, risen, pleading;\nThen welcome day, and farewell, mortal night.","note":"A hymn for when the shadows lengthen.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Warner died 1915.","denom":[]},{"id":"prot-stand-up-for-jesus","title":"Stand Up, Stand Up for Jesus","by":"George Duffield","year":1858,"trad":["presbyterian","christian"],"type":"hymn","occasion":["hope","funeral"],"text":"Stand up, stand up for Jesus,\nYe soldiers of the cross;\nLift high His royal banner,\nIt must not suffer loss;\nFrom victory unto victory\nHis army He shall lead,\nTill every foe is vanquished,\nAnd Christ is Lord indeed.\n\nStand up, stand up for Jesus,\nStand in His strength alone;\nThe arm of flesh will fail you,\nYe dare not trust your own;\nPut on the gospel armor,\nAnd watching unto prayer,\nWhere duty calls or danger,\nBe never wanting there.\n\nStand up, stand up for Jesus,\nThe strife will not be long;\nThis day the noise of battle,\nThe next the victor's song:\nTo him that overcometh,\nA crown of life shall be;\nHe with the King of glory\nShall reign eternally.","note":"Written after the dying words of a young Philadelphia preacher.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Duffield died 1888.","denom":[]},{"id":"prot-wonderful-words-of-life","title":"Wonderful Words of Life","by":"Philip P. Bliss","year":1874,"trad":["nondenom","christian"],"type":"hymn","occasion":["daily","gratitude"],"text":"Sing them over again to me,\nWonderful words of life,\nLet me more of their beauty see,\nWonderful words of life.\nWords of life and beauty,\nTeach me faith and duty;\nBeautiful words,\nWonderful words,\nWonderful words of life.\n\nChrist, the blessed One, gives to all\nWonderful words of life;\nSinner, list to the loving call,\nWonderful words of life.\nAll so freely given,\nWooing us to heaven,\nBeautiful words,\nWonderful words,\nWonderful words of life.\n\nSweetly echo the gospel call,\nWonderful words of life;\nOffer pardon and peace to all,\nWonderful words of life.\nJesus, only Saviour,\nSanctify forever,\nBeautiful words,\nWonderful words,\nWonderful words of life.","note":"A gospel song by Philip Bliss, the song leader for Moody's revivals.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Bliss died 1876.","denom":[]},{"id":"prot-i-love-to-hear-the-story","title":"I Love to Hear the Story","by":"Emily Huntington Miller","year":1867,"trad":["methodist","christian"],"type":"hymn","occasion":["birth","daily"],"text":"I love to hear the story\nWhich angel voices tell,\nHow once the King of glory\nCame down to earth to dwell.\nI am both weak and sinful,\nBut this I surely know,\nThe Lord came down to save me,\nBecause He loved me so.\n\nI'm glad my blessed Saviour\nWas once a child like me,\nTo show how pure and holy\nHis little ones should be;\nAnd if I try to follow\nHis footsteps here below,\nHe never will forget me,\nBecause He loves me so.\n\nTo sing His love and mercy\nMy sweetest songs I'll raise!\nAnd though I cannot see Him,\nI know He hears my praise;\nFor He has kindly promised\nThat even I may go\nTo sing among His angels,\nBecause He loves me so.","note":"A Methodist children's hymn.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Miller died 1913.","denom":[]},{"id":"prot-god-moves-in-a-mysterious-way","title":"God Moves in a Mysterious Way","by":"William Cowper","year":1774,"trad":["baptist","christian"],"type":"hymn","occasion":["grief","comfort","hope"],"text":"God moves in a mysterious way,\nHis wonders to perform:\nHe plants His footsteps in the sea,\nAnd rides upon the storm.\n\nDeep in unfathomable mines\nOf never-failing skill,\nHe treasures up His bright designs,\nAnd works His sovereign will.\n\nYe fearful saints, fresh courage take:\nThe clouds ye so much dread\nAre big with mercy, and shall break\nIn blessings on your head.\n\nJudge not the Lord by feeble sense,\nBut trust Him for His grace;\nBehind a frowning Providence\nHe hides a smiling face.\n\nHis purposes will ripen fast,\nUnfolding every hour.\nThe bud may have a bitter taste,\nBut sweet will be the flower.\n\nBlind unbelief is sure to err,\nAnd scan His works in vain.\nGod is His own interpreter,\nAnd He will make it plain.","note":"From the Olney Hymns, a hymn of trust in hidden purposes, loved by Baptists and evangelicals.","voice":"brian","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930)","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Cowper died 1800.","denom":[]},{"id":"prot-cs-psalm-91","title":"He That Dwelleth in the Secret Place (Psalm 91:1 to 2, 9 to 11)","by":"King James Version","year":1611,"trad":["cs","christian"],"type":"scripture","occasion":["healing","comfort"],"text":"He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.\nI will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.\n\nBecause thou hast made the LORD, which is my refuge, even the most High, thy habitation;\nThere shall no evil befall thee, neither shall any plague come nigh thy dwelling.\nFor he shall give his angels charge over thee, to keep thee in all thy ways.","note":"A psalm of protection that Christian Scientists hold close in times of illness.","voice":"jenny","source":{"name":"King James Version (1611), Psalm 91:1-2, 9-11","url":"https://www.biblegateway.com/passage/?search=Psalm+91%3A1-2,+9-11&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-quaker-still-small-voice","title":"A Still Small Voice (1 Kings 19:11 to 12)","by":"King James Version","year":1611,"trad":["quaker","christian"],"type":"scripture","occasion":["peace","daily"],"text":"And he said, Go forth, and stand upon the mount before the LORD. And, behold, the LORD passed by, and a great and strong wind rent the mountains, and brake in pieces the rocks before the LORD; but the LORD was not in the wind: and after the wind an earthquake; but the LORD was not in the earthquake:\nAnd after the earthquake a fire; but the LORD was not in the fire: and after the fire a still small voice.","note":"Elijah hears God in the stillness, a passage dear to Friends who worship in silence.","voice":"brian","source":{"name":"King James Version (1611), 1 Kings 19:11-12","url":"https://www.biblegateway.com/passage/?search=1+Kings+19%3A11-12&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-blackchurch-joy-in-the-morning","title":"Joy Cometh in the Morning (Psalm 30:4 to 5, 11 to 12)","by":"King James Version","year":1611,"trad":["blackchurch","christian"],"type":"scripture","occasion":["grief","hope","funeral"],"text":"Sing unto the LORD, O ye saints of his, and give thanks at the remembrance of his holiness.\nFor his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.\n\nThou hast turned for me my mourning into dancing: thou hast put off my sackcloth, and girded me with gladness;\nTo the end that my glory may sing praise to thee, and not be silent. O LORD my God, I will give thanks unto thee for ever.","note":"Weeping for a night and joy in the morning, preached at countless homegoing services.","voice":"jenny","source":{"name":"King James Version (1611), Psalm 30:4-5, 11-12","url":"https://www.biblegateway.com/passage/?search=Psalm+30%3A4-5,+11-12&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-moravian-new-every-morning","title":"New Every Morning (Lamentations 3:22 to 26)","by":"King James Version","year":1611,"trad":["moravian","methodist","christian"],"type":"scripture","occasion":["morning","hope","grief"],"text":"It is of the LORD’s mercies that we are not consumed, because his compassions fail not.\nThey are new every morning: great is thy faithfulness.\nThe LORD is my portion, saith my soul; therefore will I hope in him.\nThe LORD is good unto them that wait for him, to the soul that seeketh him.\nIt is good that a man should both hope and quietly wait for the salvation of the LORD.","note":"Mercies new every morning, the text behind Great Is Thy Faithfulness.","voice":"brian","source":{"name":"King James Version (1611), Lamentations 3:22-26","url":"https://www.biblegateway.com/passage/?search=Lamentations+3%3A22-26&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-baptist-2-corinthians-5","title":"A House Not Made with Hands (2 Corinthians 5:1, 6 to 8)","by":"King James Version","year":1611,"trad":["baptist","christian"],"type":"scripture","occasion":["funeral","hope"],"text":"For we know that if our earthly house of this tabernacle were dissolved, we have a building of God, an house not made with hands, eternal in the heavens.\nTherefore we are always confident, knowing that, whilst we are at home in the body, we are absent from the Lord:\n(For we walk by faith, not by sight:)\nWe are confident, I say, and willing rather to be absent from the body, and to be present with the Lord.","note":"Absent from the body, present with the Lord, read at Baptist funerals.","voice":"jenny","source":{"name":"King James Version (1611), 2 Corinthians 5:1, 6-8","url":"https://www.biblegateway.com/passage/?search=2+Corinthians+5%3A1,+6-8&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]},{"id":"prot-methodist-micah-6","title":"What Doth the Lord Require (Micah 6:8)","by":"King James Version","year":1611,"trad":["methodist","ucc","christian"],"type":"scripture","occasion":["daily","blessing"],"text":"He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?","note":"A short charge to do justly, love mercy, and walk humbly, read at services of witness to a life.","voice":"brian","source":{"name":"King James Version (1611), Micah 6:8","url":"https://www.biblegateway.com/passage/?search=Micah+6%3A8&version=KJV"},"rights":"pd","pd":"King James Version, 1611.","denom":[]}];
